.lista {
  display: grid;
  gap: 12px;
  padding: 16px;
}

/* a partir de 640px, duas colunas */
@media (min-width: 640px) {
  .lista {
    grid-template-columns: repeat(2, 1fr);
  }
}

.barra {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;   /* sem isto, a barra estoura a largura no celular */
}

/* quebra em tela de 360px */
.card { width: 400px; }

/* funciona em qualquer largura */
.card { max-width: 400px; width: 100%; }

