async function buscarPedidos(status) {
  const resposta = await fetch(`/api/pedidos?status=${encodeURIComponent(status)}`)

  if (!resposta.ok) {
    throw new Error(`falha ao buscar pedidos: HTTP ${resposta.status}`)
  }

  return resposta.json()
}

async function atualizarLista(status) {
  mostrar('carregando')
  try {
    const pedidos = await buscarPedidos(status)
    if (pedidos.length === 0) {
      mostrar('vazio')     // não é erro: é resultado
      return
    }
    mostrar('sucesso', pedidos)
  } catch (erro) {
    console.error(erro)
    mostrar('erro')        // mensagem curta, com opção de tentar de novo
  }
}

